package com.oracle.banking.customer.controller;
import com.oracle.banking.customer.dto.CustomerDtos.*; import com.oracle.banking.customer.exception.CustomerExceptions.Unauthorized; import com.oracle.banking.customer.service.CustomerService; import com.oracle.banking.shared.constants.SecurityConstants; import jakarta.validation.Valid; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/customers") public class InternalCustomerController {private final CustomerService s;private final String key;public InternalCustomerController(CustomerService s,@Value("${services.internal-api-key}")String k){this.s=s;key=k;}@PostMapping ResponseEntity<Response> create(@RequestHeader(SecurityConstants.INTERNAL_API_KEY_HEADER)String k,@Valid @RequestBody Create r){if(!key.equals(k))throw new Unauthorized("Invalid internal API key");return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}}
